<?php
namespace App\Jobs;
use App\Enums\ServerTrackingDispatchStatus; use App\Models\ServerTrackingDispatch; use App\Models\ServerTrackingAttempt; use App\Tracking\Ga4ServerPayloadFactory; use App\Tracking\MetaServerPayloadFactory; use Illuminate\Bus\Queueable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Foundation\Bus\Dispatchable; use Illuminate\Queue\InteractsWithQueue; use Illuminate\Queue\SerializesModels; use Illuminate\Support\Facades\Http; use Throwable;
class DispatchServerTracking implements ShouldQueue { use Dispatchable,InteractsWithQueue,Queueable,SerializesModels; public int $tries=3; public array $backoff=[5,30,120]; public function __construct(public int $dispatchId){} public function handle(Ga4ServerPayloadFactory $ga4,MetaServerPayloadFactory $meta):void{$d=ServerTrackingDispatch::with('groundTruthEvent.experimentRun')->findOrFail($this->dispatchId);if($d->status===ServerTrackingDispatchStatus::EndpointAccepted)return;$n=$d->attempt_count+1;$a=ServerTrackingAttempt::create(['server_tracking_dispatch_id'=>$d->id,'attempt_number'=>$n,'started_at'=>now(),'outcome'=>'processing']);$d->update(['status'=>ServerTrackingDispatchStatus::Processing,'attempt_count'=>$n,'first_attempted_at'=>$d->first_attempted_at??now()]);$start=microtime(true);try{if($d->provider==='ga4'){$payload=$ga4->make($d->groundTruthEvent);$url=config('tracking.ga4.server_endpoint').'?measurement_id='.rawurlencode(config('tracking.ga4.server_measurement_id')).'&api_secret='.rawurlencode(config('tracking.ga4.server_api_secret'));$response=Http::connectTimeout(3)->timeout(10)->post($url,$payload); }else{$context=['test_event_code'=>config('tracking.meta.capi_test_event_code')];$payload=$meta->make($d->groundTruthEvent,$context);$url='https://graph.facebook.com/'.config('tracking.meta.graph_api_version').'/'.config('tracking.meta.pixel_id').'/events';$response=Http::connectTimeout(3)->timeout(10)->post($url,['access_token'=>config('tracking.meta.capi_access_token')]+$payload);} $body=$response->json()??[];$ok=$d->provider==='ga4'?$response->successful():($response->successful()&&(($body['events_received']??0)>=1));$outcome=$ok?'endpoint_accepted':($response->status()>=500||$response->status()===429?'http_error':'provider_rejected');$a->update(['finished_at'=>now(),'latency_ms'=>(int)((microtime(true)-$start)*1000),'http_status'=>$response->status(),'outcome'=>$outcome,'response_payload'=>$body]);$d->update(['request_payload'=>$payload,'response_payload'=>$body,'last_http_status'=>$response->status(),'status'=>$ok?ServerTrackingDispatchStatus::EndpointAccepted:ServerTrackingDispatchStatus::Failed,'accepted_at'=>$ok?now():null,'failed_at'=>$ok?null:now()]);if(!$ok&&($response->status()===429||$response->status()>=500))throw new \RuntimeException('Transient provider HTTP '.$response->status());}catch(Throwable $e){$a->update(['finished_at'=>now(),'latency_ms'=>(int)((microtime(true)-$start)*1000),'outcome'=>'connection_error','error_message'=>$e->getMessage()]);$d->update(['status'=>ServerTrackingDispatchStatus::Failed,'failed_at'=>now(),'last_error_code'=>class_basename($e),'last_error_message'=>$e->getMessage()]);throw $e;}} }
